// bin2c - embeds binary files into a C++ translation unit as byte arrays.
//
// usage: bin2c <output.cpp> <header> <namespace> <symbol>=<file> [<symbol>=<file> ...]
//
// For every <symbol>=<file> pair the generated file defines
//     const unsigned char <symbol>[]          the file's bytes, verbatim
//     const std::size_t   <symbol>Size        the byte count
// inside <namespace>. The hand-written <header> (included first) must declare both as `extern`, which is what
// gives these const objects external linkage.
//
// Deliberately dependency-free (no Python, no CMake scripting) so the build works the same on every host and the
// embedded bytes are exactly the audited files.
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

namespace {

bool read_file(const std::string& path, std::vector<unsigned char>& out) {
    std::FILE* f = std::fopen(path.c_str(), "rb");
    if (!f) return false;
    unsigned char buffer[65536];
    size_t n = 0;
    while ((n = std::fread(buffer, 1, sizeof buffer, f)) > 0) out.insert(out.end(), buffer, buffer + n);
    const bool ok = std::ferror(f) == 0;
    std::fclose(f);
    return ok;
}

} // namespace

int main(int argc, char** argv) {
    if (argc < 5) {
        std::fprintf(stderr, "usage: bin2c <output.cpp> <header> <namespace> <symbol>=<file> [...]\n");
        return 2;
    }
    const std::string out_path = argv[1];
    const std::string header = argv[2];
    const std::string ns = argv[3];

    std::FILE* out = std::fopen(out_path.c_str(), "wb");
    if (!out) {
        std::fprintf(stderr, "bin2c: cannot write %s\n", out_path.c_str());
        return 1;
    }

    std::fprintf(out, "// Generated by bin2c. DO NOT EDIT.\n#include \"%s\"\n\n", header.c_str());
    // Open nested namespaces (a::b::c).
    std::vector<std::string> parts;
    for (size_t pos = 0; pos <= ns.size();) {
        const size_t next = ns.find("::", pos);
        const size_t end = next == std::string::npos ? ns.size() : next;
        if (end > pos) parts.push_back(ns.substr(pos, end - pos));
        if (next == std::string::npos) break;
        pos = next + 2;
    }
    for (const std::string& p : parts) std::fprintf(out, "namespace %s {\n", p.c_str());
    std::fprintf(out, "\n");

    for (int i = 4; i < argc; ++i) {
        const std::string arg = argv[i];
        const size_t eq = arg.find('=');
        if (eq == std::string::npos || eq == 0 || eq + 1 >= arg.size()) {
            std::fprintf(stderr, "bin2c: bad argument '%s' (expected symbol=file)\n", arg.c_str());
            std::fclose(out);
            return 2;
        }
        const std::string symbol = arg.substr(0, eq);
        const std::string path = arg.substr(eq + 1);
        std::vector<unsigned char> data;
        if (!read_file(path, data) || data.empty()) {
            std::fprintf(stderr, "bin2c: cannot read (or empty): %s\n", path.c_str());
            std::fclose(out);
            return 1;
        }

        std::fprintf(out, "const unsigned char %s[] = {\n", symbol.c_str());
        for (size_t j = 0; j < data.size(); ++j) {
            std::fprintf(out, "%u,", static_cast<unsigned>(data[j]));
            if ((j + 1) % 32 == 0) std::fprintf(out, "\n");
        }
        std::fprintf(out, "\n};\n");
        std::fprintf(out, "const std::size_t %sSize = %zu;\n\n", symbol.c_str(), data.size());
    }

    for (size_t i = parts.size(); i > 0; --i) std::fprintf(out, "} // namespace %s\n", parts[i - 1].c_str());
    const bool ok = std::fclose(out) == 0;
    return ok ? 0 : 1;
}
